/bin/zsh -lc "python3 - <<'PY'
import json,re
from pathlib import Path
root=Path('.')
data=json.loads(Path('fixtures/cases.json').read_text())
assert set(data)=={'schema_version','contract','cases'}
assert data['schema_version']==1 and data['contract']=='cronwords/draft-0'
ids=set()
counts={'required':0,'pending':0}
for c in data['cases']:
    assert c['id'] not in ids,c['id']
    ids.add(c['id'])
    assert c['status'] in counts
    counts[c['status']]+=1
    assert isinstance(c['args'],list)
    allowed={'id','status','rule','args','expected'}
    if c['status']=='pending':
        allowed|={'blocked_by','note'}
        assert c['rule']=='schedule-pending' and c['blocked_by']=='dialect-profile' and c['note']
    else:
        assert c['rule'] in {'I1','I2'} and 'expected' in c
        args=c['args']
        if c['rule']=='I1':
            assert not args or not isinstance(args[0],str)
            assert c['expected']=={'ok':False,'error':'INVALID_INPUT'}
        else:
            assert len(args)==1 and isinstance(args[0],str) and not args[0].strip(' \\t\\r\\n')
            assert c['expected']=={'ok':False,'error':'EMPTY_EXPRESSION'}
    assert not set(c)-allowed
    if 'expected' in c:
        result=c['expected']
        assert type(result['ok']) is bool
        assert set(result)==({'ok','text'} if result['ok'] else {'ok','error'})
        assert isinstance(result['text'] if result['ok'] else result['error'],str)
        if result['ok']:
            assert result['text'][0].isupper() and result['text'].endswith('.')
for file in [Path('README.md'),Path('SPEC.md'),Path('INSTALL.md'),Path('fixtures/README.md')]:
    for target in re.findall(r'\\]\\((["'^)]+)'"\\)',file.read_text()):
        assert (file.parent/target).is_file(),(file,target)
assert Path('LICENSE').read_bytes()==b'Existing license fixture: retained verbatim for this evaluation.\\n'
print('Validated JSON schema, unique IDs, required boundary expectations, candidate result shapes, local Markdown links, and unchanged license.')
print(f'Fixture inventory: {len(ids)} records; {counts[\"required\"]} required draft cases; {counts[\"pending\"]} pending cases.')
print('No implementation generated or conformance cases executed.')
PY"
